package com.example.approval.domain;
import org.junit.jupiter.api.Test; import java.time.Instant; import static org.assertj.core.api.Assertions.*;
class ExpenseRequestTest { Instant now=Instant.parse("2026-01-01T00:00:00Z"); UserId owner=new UserId("owner"), manager=new UserId("manager"); ExpenseRequest draft(){return ExpenseRequest.draft(ExpenseRequestId.newId(),owner,manager,Money.of("12.30","USD"),"Taxi",now);}
@Test void createsDraftAndRejectsSelfApprovalAssignment(){assertThat(draft().status()).isEqualTo(RequestStatus.DRAFT);assertThatThrownBy(()->ExpenseRequest.draft(ExpenseRequestId.newId(),owner,owner,Money.of("1","USD"),"x",now)).isInstanceOf(InvalidRequestDataException.class);}
@Test void rejectsInvalidMoney(){assertThatThrownBy(()->Money.of("0","USD")).isInstanceOf(InvalidMonetaryValueException.class);assertThatThrownBy(()->Money.of("1.001","USD")).isInstanceOf(InvalidMonetaryValueException.class);assertThatThrownBy(()->Money.of("1","ZZZ")).isInstanceOf(InvalidMonetaryValueException.class);}
@Test void submitsApprovesAndRecordsEvents(){var r=draft();r.submit(now);r.approve(manager,now);assertThat(r.status()).isEqualTo(RequestStatus.APPROVED);assertThat(r.version()).isEqualTo(2);assertThat(r.history()).hasSize(2);assertThat(r.history().get(0)).isInstanceOf(ExpenseSubmitted.class);assertThat(r.history().get(1).occurredAt()).isEqualTo(now);}
@Test void rejectsUnauthorizedActorsAndInvalidTransitionsWithoutMutation(){var r=draft();r.submit(now);long version=r.version();int events=r.history().size();assertThatThrownBy(()->r.approve(owner,now)).isInstanceOf(UnauthorizedActorException.class);assertThatThrownBy(()->r.reject(new UserId("other"),"no",now)).isInstanceOf(UnauthorizedActorException.class);assertThatThrownBy(()->r.reject(manager," ",now)).isInstanceOf(InvalidRequestDataException.class);assertThat(r.version()).isEqualTo(version);assertThat(r.history()).hasSize(events);}
@Test void rejectsDraftWithdrawalAndRepeatedDecision(){var r=draft();assertThatThrownBy(()->r.withdraw(owner,now)).isInstanceOf(InvalidStateTransitionException.class);r.submit(now);r.reject(manager,"missing receipt",now);assertThatThrownBy(()->r.approve(manager,now)).isInstanceOf(InvalidStateTransitionException.class);assertThat(r.status()).isEqualTo(RequestStatus.REJECTED);}
@Test void ownerCanWithdrawPendingRequest(){var r=draft();r.submit(now);r.withdraw(owner,now);assertThat(r.status()).isEqualTo(RequestStatus.WITHDRAWN);assertThat(r.history().get(1)).isInstanceOf(ExpenseWithdrawn.class);}
}
